TlsCipherMode TLSCipherSuiteGetMode(uint16_t cipher_suite)
{
    size_t n = sizeof(tls_cipher_mode_table) / sizeof(tls_cipher_mode_table[0]);
    for (size_t i = 0; i < n; i++) {
        if (tls_cipher_mode_table[i].cipher_suite == cipher_suite) {
            return tls_cipher_mode_table[i].mode;
        }
    }
    return TLS_CIPHER_MODE_UNKNOWN;
}

const char *TLSCipherSuiteGetName(uint16_t cipher_suite)
{
    size_t n = sizeof(tls_cipher_mode_table) / sizeof(tls_cipher_mode_table[0]);
    for (size_t i = 0; i < n; i++) {
        if (tls_cipher_mode_table[i].cipher_suite == cipher_suite) {
            return tls_cipher_mode_table[i].name;
        }
    }
    return NULL;
}